<?php
require __DIR__.'/config.php'; $method=$_SERVER['REQUEST_METHOD']??''; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;
if($method==='GET'){$user=current_user();if($id){$q=db()->prepare('SELECT * FROM productos WHERE id=?'.(!$user||$user['rol']!=='ADMIN'?" AND estado='ACTIVO'":''));$q->execute([$id]);$row=$q->fetch();if(!$row)json_response(false,null,'Producto no encontrado.',404);json_response(true,$row,'Producto consultado.');}$sql='SELECT * FROM productos'.(!$user||$user['rol']!=='ADMIN'?" WHERE estado='ACTIVO'":'').' ORDER BY created_at DESC';json_response(true,db()->query($sql)->fetchAll(),'Productos consultados.');}
require_admin(); if(in_array($method,['POST','PUT','DELETE'],true))require_csrf();
if($method==='POST'||$method==='PUT'){$data=body();$name=trim((string)($data['nombre']??''));$description=trim((string)($data['descripcion']??''));$price=filter_var($data['precio']??null,FILTER_VALIDATE_FLOAT);$stock=filter_var($data['stock']??null,FILTER_VALIDATE_INT);$image=trim((string)($data['imagen']??''));$state=$data['estado']??'ACTIVO';if($name===''||mb_strlen($name)>140||$price===false||$price<0||$stock===false||$stock<0||!in_array($state,['ACTIVO','INACTIVO'],true))json_response(false,null,'Revisa nombre, precio, stock y estado del producto.',400);
 if($image!==''&&!preg_match('#^uploads/productos/[a-f0-9]{32}\.(jpg|png|webp)$#i',$image))json_response(false,null,'La imagen seleccionada no es válida.',400);
 if($method==='POST'){$q=db()->prepare('INSERT INTO productos(nombre,descripcion,precio,stock,imagen,estado) VALUES(?,?,?,?,?,?)');$q->execute([$name,$description,$price,$stock,$image?:null,$state]);json_response(true,['id'=>(int)db()->lastInsertId()],'Producto creado correctamente.',201);}
 if(!$id)$id=(int)($data['id']??0);if(!$id)json_response(false,null,'Indica el producto que deseas actualizar.',400);$q=db()->prepare('UPDATE productos SET nombre=?,descripcion=?,precio=?,stock=?,imagen=COALESCE(?,imagen),estado=? WHERE id=?');$q->execute([$name,$description,$price,$stock,$image?:null,$state,$id]);if(!$q->rowCount()){$check=db()->prepare('SELECT id FROM productos WHERE id=?');$check->execute([$id]);if(!$check->fetch())json_response(false,null,'Producto no encontrado.',404);}json_response(true,null,'Producto actualizado correctamente.');}
if($method==='DELETE'){if(!$id)json_response(false,null,'Indica el producto que deseas desactivar.',400);$q=db()->prepare("UPDATE productos SET estado='INACTIVO' WHERE id=?");$q->execute([$id]);if(!$q->rowCount())json_response(false,null,'Producto no encontrado o ya estaba inactivo.',404);json_response(true,null,'Producto desactivado correctamente.');}
require_method(['GET','POST','PUT','DELETE']);
